function nextPermutation(nums) {
    const n = nums.length;

    // Step 1: Find the first decreasing element from the right (pivot `k`)
    let k = n - 2;
    while (k >= 0 && nums[k] >= nums[k + 1]) {
        k--;
    }

    // If no such element exists, the array is in descending order.
    // Reverse the entire array to get the smallest permutation.
    if (k === -1) {
        reverse(nums, 0, n - 1);
        return;
    }

    // Step 2: Find the smallest element to the right of `k` that is greater than `nums[k]` (pivot `l`)
    let l = n - 1;
    while (l > k && nums[l] <= nums[k]) {
        l--;
    }

    // Step 3: Swap `nums[k]` and `nums[l]` 
    swap(nums, k, l);

    // Step 4: Reverse the subarray from `k + 1` to the end
    reverse(nums, k + 1, n - 1);
}

function swap(arr, i, j) {
    [arr[i], arr[j]] = [arr[j], arr[i]];
}

function reverse(arr, start, end) {
    while (start < end) {
        swap(arr, start, end);
        start++;
        end--;
    }
}
